 idx: bool) -> bool {\\r\\n 173:     if !rows.is_empty() && rows[0][0].len() == 3 && rows[0][0] == \\\"\\\\u{FEFF}\\\" {\\r\\n 174:         return true;\\r\\n 175:     }\\r\\n 176:     let wrk = Workdir::new(name);\\r\\n 177:     if idx {\\r\\n 178:         wrk.create_indexed(\\\"in.csv\\\", rows.clone());\\r\\n 179:     } else {\\r\\n 180:         wrk.create(\\\"in.csv\\\", rows.clone());\\r\\n 181:     }\\r\\n 182: \\r\\n 183:     let mut cmd = wrk.command(\\\"frequency\\\");\\r\\n 184:     cmd.arg(\\\"in.csv\\\").args(&[\\\"-j\\\", \\\"4\\\"]).args(&[\\\"--limit\\\", \\\"0\\\"]);\\r\\n 185: \\r\\n 186:     let stdout = wrk.stdout::<String>(&mut cmd);\\r\\n 187:     let got_ftables = ftables_from_csv_string(stdout);\\r\\n 188:     let expected_ftables = ftables_from_rows(rows);\\r\\n 189:     assert_eq_ftables(&got_ftables, &expected_ftables)\\r\\n 190: }\\r\\n 191: \\r\\n 192: type FTables = HashMap<String, Frequencies<String>>;\\r\\n 193: \\r\\n 194: #[derive(Deserialize)]\\r\\n 195: struct FRow {\\r\\n 196:     field: String,\\r\\n 197:     value: String,\\r\\n 198:     count: usize,\\r\\n 199: }\\r\\n 200: \\r\\n 201: fn ftables_from_rows<T: Csv>(rows: T) -> FTables {\\r\\n 202:     let mut rows = rows.to_vecs();\\r\\n 203:     if rows.len() <= 1 {\\r\\n 204:         return HashMap::new();\\r\\n 205:     }\\r\\n 206: \\r\\n 207:     let header = rows.remove(0);\\r\\n 208:     let mut ftables = HashMap::new();\\r\\n 209:     for field in header.iter() {\\r\\n 210:         ftables.insert(field.clone(), Frequencies::new());\\r\\n 211:     }\\r\\n 212:     for row in rows.into_iter() {\\r\\n 213:         for (i, mut field) in row.into_iter().enumerate() {\\r\\n 214:             field = field.trim().to_owned();\\r\\n 215:             if field.is_empty() {\\r\\n 216:                 field = \\\"(NULL)\\\".to_owned();\\r\\n 217:             }\\r\\n 218:             ftables.get_mut(&header[i]).unwrap().add(field);\\r\\n 219:         }\\r\\n 220:     }\\r\\n 221:     ftables\\r\\n 222: }\\r\\n 223: \\r\\n 224: fn ftables_from_csv_string(data: String) -> FTables {\\r\\n 225:     let mut rdr = csv::Reader::from_reader(data.as_bytes());\\r\\n 226:     let mut ftables = HashMap::new();\\r\\n 227:     for frow in rdr.deserialize() {\\r\\n 228:         let frow: FRow = frow.unwrap();\\r\\n 229:         match ftables.entry(frow.field) {\\r\\n 230:             Entry::Vacant(v) => {\\r\\n 231:                 let mut ftable = Frequencies::new();\\r\\n 232:                 for _ in 0..frow.count {\\r\\n 233:                     ftable.add(frow.value.clone());\\r\\n 234:                 }\\r\\n 235:                 v.insert(ftable);\\r\\n 236:             }\\r\\n 237:             Entry::Occupied(mut v) => {\\r\\n 238:                 for _ in 0..frow.count {\\r\\n 239:                     v.get_mut().add(frow.value.clone());\\r\\n 240:                 }\\r\\n 241:             }\\r\\n 242:         }\\r\\n 243:     }\\r\\n 244:     ftables\\r\\n 245: }\\r\\n 246: \\r\\n 247: fn freq_data<T>(ftable: &Frequencies<T>) -> Vec<(&T, u64)>\\r\\n 248:         where T: ::std::hash::Hash + Ord + Clone {\\r\\n 249:     let mut freqs = ftable.most_frequent();\\r\\n 250:     freqs.sort();\\r\\n 251:     freqs\\r\\n 252: }\\r\\n 253: \\r\\n 254: fn assert_eq_ftables(got: &FTables, expected: &FTables) -> bool {\\r\\n 255:     for (k, v) in got.iter() {\\r\\n 256:         assert_eq!(freq_data(v), freq_data(expected.get(k).unwrap()));\\r\\n 257:     }\\r\\n 258:     for (k, v) in expected.iter() {\\r\\n 259:         assert_eq!(freq_data(got.get(k).unwrap()), freq_data(v));\\r\\n 260:     }\\r\\n 261:     true\\r\\n 262: }\\r\\n\"}","command":"shell_command","command_index":6,"command_line":"{\"command\":\"$files=@('rust-reference/tests/test_fmt.rs','rust-reference/tests/test_stats.rs','rust-reference/tests/test_frequency.rs'); foreach($f in $files){\\\"===== $f =====\\\"; $n=0; Get-Content $f | ForEach-Object {$n++; \\\"{0,4}: {1}\\\" -f $n,$_}}\",\"workdir\"