\\");\\r\\n 151: stats_tests!(stats_sum_nulls2, \\\"sum\\\", &[\\\"\\\", \\\"1\\\", \\\"2\\\"], \\\"3\\\");\\r\\n 152: \\r\\n 153: stats_tests!(stats_min, \\\"min\\\", &[\\\"2\\\", \\\"1.1\\\"], \\\"1.1\\\");\\r\\n 154: stats_tests!(stats_max, \\\"max\\\", &[\\\"2\\\", \\\"1.1\\\"], \\\"2\\\");\\r\\n 155: stats_tests!(stats_min_mix, \\\"min\\\", &[\\\"2\\\", \\\"a\\\", \\\"1.1\\\"], \\\"1.1\\\");\\r\\n 156: stats_tests!(stats_max_mix, \\\"max\\\", &[\\\"2\\\", \\\"a\\\", \\\"1.1\\\"], \\\"a\\\");\\r\\n 157: stats_tests!(stats_min_null, \\\"min\\\", &[\\\"\\\", \\\"2\\\", \\\"1.1\\\"], \\\"1.1\\\");\\r\\n 158: stats_tests!(stats_max_null, \\\"max\\\", &[\\\"2\\\", \\\"1.1\\\", \\\"\\\"], \\\"2\\\");\\r\\n 159: \\r\\n 160: stats_tests!(stats_len_min, \\\"min_length\\\", &[\\\"aa\\\", \\\"a\\\"], \\\"1\\\");\\r\\n 161: stats_tests!(stats_len_max, \\\"max_length\\\", &[\\\"a\\\", \\\"aa\\\"], \\\"2\\\");\\r\\n 162: stats_tests!(stats_len_min_null, \\\"min_length\\\", &[\\\"\\\", \\\"aa\\\", \\\"a\\\"], \\\"0\\\");\\r\\n 163: stats_tests!(stats_len_max_null, \\\"max_length\\\", &[\\\"a\\\", \\\"aa\\\", \\\"\\\"], \\\"2\\\");\\r\\n 164: \\r\\n 165: stats_tests!(stats_mean, \\\"mean\\\", &[\\\"5\\\", \\\"15\\\", \\\"10\\\"], \\\"10\\\");\\r\\n 166: stats_tests!(stats_stddev, \\\"stddev\\\", &[\\\"1\\\", \\\"2\\\", \\\"3\\\"], \\\"0.816496580927726\\\");\\r\\n 167: stats_tests!(stats_mean_null, \\\"mean\\\", &[\\\"\\\", \\\"5\\\", \\\"15\\\", \\\"10\\\"], \\\"10\\\");\\r\\n 168: stats_tests!(stats_stddev_null, \\\"stddev\\\", &[\\\"1\\\", \\\"2\\\", \\\"3\\\", \\\"\\\"],\\r\\n 169:              \\\"0.816496580927726\\\");\\r\\n 170: stats_tests!(stats_mean_mix, \\\"mean\\\", &[\\\"5\\\", \\\"15.1\\\", \\\"9.9\\\"], \\\"10\\\");\\r\\n 171: stats_tests!(stats_stddev_mix, \\\"stddev\\\", &[\\\"1\\\", \\\"2.1\\\", \\\"2.9\\\"],\\r\\n 172:              \\\"0.7788880963698614\\\");\\r\\n 173: \\r\\n 174: stats_tests!(stats_cardinality, \\\"cardinality\\\", &[\\\"a\\\", \\\"b\\\", \\\"a\\\"], \\\"2\\\");\\r\\n 175: stats_tests!(stats_mode, \\\"mode\\\", &[\\\"a\\\", \\\"b\\\", \\\"a\\\"], \\\"a\\\");\\r\\n 176: stats_tests!(stats_mode_null, \\\"mode\\\", &[\\\"\\\", \\\"a\\\", \\\"b\\\", \\\"a\\\"], \\\"a\\\");\\r\\n 177: stats_tests!(stats_median, \\\"median\\\", &[\\\"1\\\", \\\"2\\\", \\\"3\\\"], \\\"2\\\");\\r\\n 178: stats_tests!(stats_median_null, \\\"median\\\", &[\\\"\\\", \\\"1\\\", \\\"2\\\", \\\"3\\\"], \\\"2\\\");\\r\\n 179: stats_tests!(stats_median_even, \\\"median\\\", &[\\\"1\\\", \\\"2\\\", \\\"3\\\", \\\"4\\\"], \\\"2.5\\\");\\r\\n 180: stats_tests!(stats_median_even_null, \\\"median\\\",\\r\\n 181:              &[\\\"\\\", \\\"1\\\", \\\"2\\\", \\\"3\\\", \\\"4\\\"], \\\"2.5\\\");\\r\\n 182: stats_tests!(stats_median_mix, \\\"median\\\", &[\\\"1\\\", \\\"2.5\\\", \\\"3\\\"], \\\"2.5\\\");\\r\\n 183: \\r\\n 184: mod stats_infer_nothing {\\r\\n 185:     // Only test CSV data with headers.\\r\\n 186:     // Empty CSV data with no headers won't produce any statistical analysis.\\r\\n 187:     use super::test_stats;\\r\\n 188:     stats_test_headers!(stats_infer_nothing, \\\"type\\\", &[], \\\"NULL\\\");\\r\\n 189: }\\r\\n 190: \\r\\n 191: mod stats_zero_cardinality {\\r\\n 192:     use super::test_stats;\\r\\n 193:     stats_test_headers!(stats_zero_cardinality, \\\"cardinality\\\", &[], \\\"0\\\");\\r\\n 194: }\\r\\n 195: \\r\\n 196: mod stats_zero_mode {\\r\\n 197:     use super::test_stats;\\r\\n 198:     stats_test_headers!(stats_zero_mode, \\\"mode\\\", &[], \\\"N/A\\\");\\r\\n 199: }\\r\\n 200: \\r\\n 201: mod stats_zero_mean {\\r\\n 202:     use super::test_stats;\\r\\n 203:     stats_test_headers!(stats_zero_mean, \\\"mean\\\", &[], \\\"\\\");\\r\\n 204: }\\r\\n 205: \\r\\n 206: mod stats_zero_median {\\r\\n 207:     use super::test_stats;\\r\\n 208:     stats_test_headers!(stats_zero_median, \\\"median\\\", &[], \\\"\\\");\\r\\n 209: }\\r\\n 210: \\r\\n 211: mod stats_header_fields {\\r\\n 212:     use super::test_stats;\\r\\n 213:     stats_test_headers!(stats_header_field_name, \\\"field\\\", &[\\\"a\\\"], \\\"header\\\");\\r\\n 214:     stats_test_no_headers!(stats_header_no_field_name, \\\"field\\\", &[\\\"a\\\"], \\\"0\\\");\\r\\n 215: }\\r\\n\"}","command":"shell_command","command_index":6,"command_line":"{\"command\":\"$f='rust-reference/tests/test_stats.rs'; $lines=Get-Content $f; foreach($i in 58..([Math]::Min(330,$lines.Count-1))){\\\"{0,4}: {1}\\\" -f ($i+1),$lines[$i]}\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\raw\\\\project-rebuild-source-port\\\\r-af8ea0b6c0\\\\xsv\\\\tura-direct-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c1024c5fdcf320.tool.command_run:call_iYUDly9TYmUTQsENo9lX7vqX:6","provider_tool_call_id":"call_iYUDly9TYmUTQsENo9lX7vqX","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
