{"item":{"aggregated_output":"{\"error_type\":\"ParseError\",\"exit_code\":1,\"message\":\"invalid patch line 76: content must be inside a hunk\",\"stderr\":\"invalid patch line 76: content must be inside a hunk\",\"stdout\":\"\"}","command":"apply_patch","command_index":0,"command_line":"*** Begin Patch\n*** Add File: xsv_port.py\n+#!/usr/bin/env python3\n+\"\"\"A dependency-free Python port of the benchmarked xsv 0.13.0 commands.\"\"\"\n+\n+import math\n+import os\n+import re\n+import statistics\n+import sys\n+from collections import Counter\n+from functools import cmp_to_key\n+\n+\n+COMMANDS = \"\"\"\n+    cat         Concatenate by row or column\n+    count       Count records\n+    fixlengths  Makes all records have same length\n+    flatten     Show one field per line\n+    fmt         Format CSV output (change field delimiter)\n+    frequency   Show frequency tables\n+    headers     Show header names\n+    help        Show this usage message.\n+    index       Create CSV index for faster access\n+    input       Read CSV data with special quoting rules\n+    join        Join CSV files\n+    sample      Randomly sample CSV data\n+    search      Search CSV data with regexes\n+    select      Select columns from CSV\n+    slice       Slice records from CSV\n+    sort        Sort CSV data\n+    split       Split CSV data into many files\n+    stats       Compute basic statistics\n+    table       Align CSV data into columns\n+\"\"\"\n+\n+ROOT_USAGE = \"\"\"Usage:\n+    xsv <command> [<args>...]\n+    xsv [options]\n+\n+Options:\n+    --list        List all commands available.\n+    -h, --help    Display this message\n+    <command> -h  Display the command help message\n+    --version     Print version info and exit\n+\n+Commands:\"\"\" + COMMANDS\n+\n+USAGES = {\n+\"headers\": \"\"\"Prints the fields of the first row in the CSV data.\n+\n+These names can be used in commands like 'select' to refer to columns in the\n+CSV data.\n+\n+Note that multiple CSV files may be given to this command. This is useful with\n+the --intersect flag.\n+\n+Usage:\n+    xsv headers [options] [<input>...]\n+\n+headers options:\n+    -j, --just-names       Only show the header names (hide column index).\n+                           This is automatically enabled if more than one\n+                           input is given.\n+    --intersect            Shows the intersection of all headers in all of\n+                           the inputs given.\n+\n+Common options:\n+    -h, --help             Display this message\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"count\": \"\"\"Prints a count of the number of records in the CSV data.\n+\n+Note that the count will not include the header row (unless --no-headers is\ngiven).\n+\n+Usage:\n+    xsv count [options] [<input>]\n+\n+Common options:\n+    -h, --help             Display this message\n+    -n, --no-headers       When set, the first row will not be included in\n+                           the count.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"select\": \"\"\"Select columns from CSV data efficiently.\n+\n+This command lets you manipulate the columns in CSV data. You can re-order\n+them, duplicate them or drop them. Columns can be referenced by index or by\n+name if there is a header row (duplicate column names can be disambiguated with\n+more indexing). Finally, column ranges can be specified.\n+\n+  Select the first and fourth columns:\n+  $ xsv select 1,4\n+\n+  Select the first 4 columns (by index and by name):\n+  $ xsv select 1-4\n+  $ xsv select Header1-Header4\n+\n+  Ignore the first 2 columns (by range and by omission):\n+  $ xsv select 3-\n+  $ xsv select '!1-2'\n+\n+  Select the third column named 'Foo':\n+  $ xsv select 'Foo[2]'\n+\n+  Re-order and duplicate columns arbitrarily:\n+  $ xsv select 3-1,Header3-Header1,Header1,Foo[2],Header1\n+\n+  Quote column names that conflict with selector syntax:\n+  $ xsv select '\\\"Date - Opening\\\",\\\"Date - Actual Closing\\\"'\n+\n+Usage:\n+    xsv select [options] [--] <selection> [<input>]\n+    xsv select --help\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -n, --no-headers       When set, the first row will not be interpreted\n+                           as headers. (i.e., They are not searched, analyzed,\n+                           sliced, etc.)\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"slice\": \"\"\"Returns the rows in the range specified (starting at 0, half-open interval).\n+The range does not include headers.\n+\n+If the start of the range isn't specified, then the slice starts from the first\n+record in the CSV data.\n+\n+If the end of the range isn't specified, then the slice continues to the last\n+record in the CSV data.\n+\n+This operation can be made much faster by creating an index with 'xsv index'\n+first. Namely, a slice on an index requires parsing just the rows that are\n+sliced. Without an index, all rows up to the first row in the slice must be\n+parsed.\n+\n+Usage:\n+    xsv slice [options] [<input>]\n+\n+slice options:\n+    -s, --start <arg>      The index of the record to slice from.\n+    -e, --end <arg>        The index of the record to slice to.\n+    -l, --len <arg>        The length of the slice (can be used instead\n+                           of --end).\n+    -i, --index <arg>      Slice a single record (shortcut for -s N -l 1).\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -n, --no-headers       When set, the first row will not be interpreted\n+                           as headers. Otherwise, the first row will always\n+                           appear in the output as the header row.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"search\": \"\"\"Filters CSV data by whether the given regex matches a row.\n+\n+The regex is applied to each field in each row, and if any field matches,\n+then the row is written to the output. The columns to search can be limited\n+with the '--select' flag (but the full row is still written to the output if\n+there is a match).\n+\n+Usage:\n+    xsv search [options] <regex> [<input>]\n+    xsv search --help\n+\n+search options:\n+    -i, --ignore-case      Case insensitive search. This is equivalent to\n+                           prefixing the regex with '(?i)'.\n+    -s, --select <arg>     Select the columns to search. See 'xsv select -h'\n+                           for the full syntax.\n+    -v, --invert-match     Select only rows that did not match\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -n, --no-headers       When set, the first row will not be interpreted\n+                           as headers. (i.e., They are not searched, analyzed,\n+                           sliced, etc.)\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"sort\": \"\"\"Sorts CSV data lexicographically.\n+\n+Note that this requires reading all of the CSV data into memory.\n+\n+Usage:\n+    xsv sort [options] [<input>]\n+\n+sort options:\n+    -s, --select <arg>     Select a subset of columns to sort.\n+                           See 'xsv select --help' for the format details.\n+    -N, --numeric          Compare according to string numerical value\n+    -R, --reverse          Reverse order\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -n, --no-headers       When set, the first row will not be interpreted\n+                           as headers. Namely, it will be sorted with the rest\n+                           of the rows. Otherwise, the first row will always\n+                           appear as the header row in the output.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"table\": \"\"\"Outputs CSV data as a table with columns in alignment.\n+\n+This will not work well if the CSV data contains large fields.\n+\n+Note that formatting a table requires buffering all CSV data into memory.\n+Therefore, you should use the 'sample' or 'slice' command to trim down large\n+CSV data before formatting it with this command.\n+\n+Usage:\n+    xsv table [options] [<input>]\n+\n+table options:\n+    -w, --width <arg>      The minimum width of each column.\n+                           [default: 2]\n+    -p, --pad <arg>        The minimum number of spaces between each column.\n+                           [default: 2]\n+    -c, --condense <arg>  Limits the length of each field to the value\n+                           specified. If the field is UTF-8 encoded, then\n+                           <arg> refers to the number of code points.\n+                           Otherwise, it refers to the number of bytes.\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"fmt\": \"\"\"Formats CSV data with a custom delimiter or CRLF line endings.\n+\n+Generally, all commands in xsv output CSV data in a default format, which is\n+the same as the default format for reading CSV data. This makes it easy to\n+pipe multiple xsv commands together. However, you may want the final result to\n+have a specific delimiter or record separator, and this is where 'xsv fmt' is\n+useful.\n+\n+Usage:\n+    xsv fmt [options] [<input>]\n+\n+fmt options:\n+    -t, --out-delimiter <arg>  The field delimiter for writing CSV data.\n+                               [default: ,]\n+    --crlf                     Use '\\\\r\\\\n' line endings in the output.\n+    --ascii                    Use ASCII field and record separators.\n+    --quote <arg>              The quote character to use. [default: \\\" ]\n+    --quote-always             Put quotes around every value.\n+    --escape <arg>             The escape character to use. When not specified,\n+                               quotes are escaped by doubling them.\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"stats\": \"\"\"Computes basic statistics on CSV data.\n+\n+Basic statistics includes mean, median, mode, standard deviation, sum, max and\n+min values. Note that some statistics are expensive to compute, so they must\n+be enabled explicitly. By default, the following statistics are reported for\n+*every* column in the CSV data: mean, max, min and standard deviation. The\n+default set of statistics corresponds to statistics that can be computed\n+efficiently on a stream of data (i.e., constant memory).\n+\n+Computing statistics on a large file can be made much faster if you create\n+an index for it first with 'xsv index'.\n+\n+Usage:\n+    xsv stats [options] [<input>]\n+\n+stats options:\n+    -s, --select <arg>     Select a subset of columns to compute stats for.\n+                           See 'xsv select --help' for the format details.\n+                           This is provided here because piping 'xsv select'\n+                           into 'xsv stats' will disable the use of indexing.\n+    --everything           Show all statistics available.\n+    --mode                 Show the mode.\n+                           This requires storing all CSV data in memory.\n+    --cardinality          Show the cardinality.\n+                           This requires storing all CSV data in memory.\n+    --median               Show the median.\n+                           This requires storing all CSV data in memory.\n+    --nulls                Include NULLs in the population size for computing\n+                           mean and standard deviation.\n+    -j, --jobs <arg>       The number of jobs to run in parallel.\n+                           This works better when the given CSV data has\n+                           an index already created. Note that a file handle\n+                           is opened for each job.\n+                           When set to '0', the number of jobs is set to the\n+                           number of CPUs detected.\n+                           [default: 0]\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -n, --no-headers       When set, the first row will NOT be interpreted\n+                           as column names. i.e., They will be included\n+                           in statistics.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+\"frequency\": \"\"\"Compute a frequency table on CSV data.\n+\n+The frequency table is formatted as CSV data:\n+\n+    field,value,count\n+\n+By default, there is a row for the N most frequent values for each field in the\n+data. The order and number of values can be tweaked with --asc and --limit,\n+respectively.\n+\n+Since this computes an exact frequency table, memory proportional to the\n+cardinality of each column is required.\n+\n+Usage:\n+    xsv frequency [options] [<input>]\n+\n+frequency options:\n+    -s, --select <arg>     Select a subset of columns to compute frequencies\n+                           for. See 'xsv select --help' for the format\n+                           details. This is provided here because piping 'xsv\n+                           select' into 'xsv frequency' will disable the use\n+                           of indexing.\n+    -l, --limit <arg>      Limit the frequency table to the N most common\n+                           items. Set to '0' to disable a limit.\n+                           [default: 10]\n+    -a, --asc              Sort the frequency tables in ascending order by\n+                           count. The default is descending order.\n+    --no-nulls             Don't include NULLs in the frequency table.\n+    -j, --jobs <arg>       The number of jobs to run in parallel.\n+                           This works better when the given CSV data has\n+                           an index already created. Note that a file handle\n+                           is opened for each job.\n+                           When set to '0', the number of jobs is set to the\n+                           number of CPUs detected.\n+                           [default: 0]\n+\n+Common options:\n+    -h, --help             Display this message\n+    -o, --output <file>    Write output to <file> instead of stdout.\n+    -n, --no-headers       When set, the first row will NOT be included\n+                           in the frequency table. Additionally, the 'field'\n+                           column will be 1-based indices instead of header\n+                           names.\n+    -d, --delimiter <arg>  The field delimiter for reading CSV data.\n+                           Must be a single character. (default: ,)\n+\"\"\",\n+}\n+\n+\n+class CliError(Exception):\n+    def __init__(self, message, partial=b\"\"):\n+        super().__init__(message)\n+        self.message = message\n+        self.partial = partial\n+\n+\n+class CsvError(CliError):\n+    pass\n+\n+\n+def delimiter(value):\n+    if value == r\"\\t\":\n+        return 9\n+    raw = value.encode(\"utf-8\")\n+    if len(raw) != 1:\n+        if len(value) == 1:\n+            raise CliError(\"Could not convert '{}' to ASCII delimiter.\".format(value))\n+        raise CliError(\"Could not convert '{}' to a single ASCII character.\".format(value))\n+    return raw[0]\n+\n+\n+def inferred_delimiter(path):\n+    return 9 if path not in (None, \"-\") and path.endswith(\".tsv\") else 44\n+\n+\n+def parse_options(args, aliases, values, defaults=None):\n+    opts = dict(defaults or {})\n+    pos = []\n+    stop = False\n+    i = 0\n+    while i < len(args):\n+        arg = args[i]\n+        if stop or arg == \"-\" or not arg.startswith(\"-\"):\n+            pos.append(arg)\n+            i += 1\n+            continue\n+        if arg == \"--\":\n+            stop = True\n+            i += 1\n+            continue\n+        if arg in (\"-h\", \"--help\"):\n+            opts[\"help\"] = True\n+            i += 1\n+            continue\n+        name, eq, attached = arg.partition(\"=\")\n+        canonical = aliases.get(name)\n+        if canonical is None and len(name) > 2 and name[0] == \"-\" and name[1] != \"-\":\n+            canonical = aliases.get(name[:2])\n+            if canonical in values:\n+                attached = name[2:]\n+                eq = \"=\"\n+        if canonical is None:\n+            raise CliError(\"Unknown flag: '{}'\".format(arg))\n+        if canonical in values:\n+            if not eq:\n+                i += 1\n+                if i >= len(args):\n+                    raise CliError(\"Argument '{}' requires a value\".format(name))\n+                attached = args[i]\n+            opts[canonical] = attached\n+        else:\n+            opts[canonical] = True\n+        i += 1\n+    return opts, pos\n+\n+\n+def uint(value, name):\n+    if not re.fullmatch(r\"[0-9]+\", value or \"\"):\n+        raise CliError(\"Invalid value for {}: '{}'\".format(name, value))\n+    return int(value)\n+\n+\n+def read_input(path):\n+    if path in (None, \"-\"):\n+        return sys.stdin.buffer.read()\n+    try:\n+        with open(path, \"rb\") as stream:\n+            return stream.read()\n+    except OSError as error:\n+        raise CliError(\"failed to open {}: {}\".format(path, error.strerror or error))\n+\n+\n+def parse_csv(data, delim=44, quoting=True, quote=34, escape=None):\n+    if data.startswith(b\"\\xef\\xbb\\xbf\"):\n+        data = data[3:]\n+    rows = []\n+    row = []\n+    field = bytearray()\n+    in_quotes = False\n+    field_started = False\n+    row_started = False\n+    line = 1\n+    record_start = 0\n+    positions = []\n+    i = 0\n+    while i < len(data):\n+        byte = data[i]\n+        if in_quotes:\n+            if escape is not None and byte == escape and i + 1 < len(data):\n+                i += 1\n+                field.append(data[i])\n+            elif byte == quote:\n+                if i + 1 < len(data) and data[i + 1] == quote:\n+                    field.append(quote)\n+                    i += 1\n+                else:\n+                    in_quotes = False\n+            else:\n+                field.append(byte)\n+                if byte == 10:\n+                    line += 1\n+            i += 1\n+            continue\n+        if quoting and byte == quote and not field_started:\n+            in_quotes = True\n+            field_started = True\n+            row_started = True\n+        elif byte == delim:\n+            row.append(bytes(field))\n+            field.clear()\n+            field_started = False\n+            row_started = True\n+        elif byte == 10:\n+            if row_started or field_started or field:\n+                if field.endswith(b\"\\r\"):\n+                    del field[-1]\n+                row.append(bytes(field))\n+                rows.append(row)\n+                positions.append((record_start, line))\n+            row = []\n+            field = bytearray()\n+            field_started = False\n+            row_started = False\n+            line += 1\n+            record_start = i + 1\n+        else:\n+            field.append(byte)\n+            field_started = True\n+            row_started = True\n+        i += 1\n+    if row_started or field_started or field or row:\n+        if field.endswith(b\"\\r\") and not in_quotes:\n+            del field[-1]\n+        row.append(bytes(field))\n+        rows.append(row)\n+        positions.append((record_start, line))\n+    if rows:\n+        expected = len(rows[0])\n+        for idx, current in enumerate(rows[1:], 1):\n+            if len(current) != expected:\n+                byte, row_line = positions[idx]\n+                raise CsvError(\n+                    \"CSV error: record {} (line: {}, byte: {}): found record with {} fields, \"\n+                    \"but the previous record has {} fields\".format(\n+                        idx, row_line, byte, len(current), expected))\n+    return rows\n+\n+\n+def read_csv(path, delim, no_headers=False):\n+    rows = parse_csv(read_input(path), delim)\n+    first = rows[0] if rows else []\n+    records = rows if no_headers else rows[1:]\n+    return first, records, rows\n+\n+\n+def quote_field(field, delim, quote=34, always=False, escape=None, single=False):\n+    needed = always or delim in field or quote in field or 10 in field or 13 in field\n+    if single and not field:\n+        needed = True\n+    if not needed:\n+        return field\n+    if escape is None:\n+        body = field.replace(bytes([quote]), bytes([quote, quote]))\n+    else:\n+        body = field.replace(bytes([quote]), bytes([escape, quote]))\n+    return bytes([quote]) + body + bytes([quote])\n+\n+\n+def encode_rows(rows, delim=44, term=b\"\\n\", quote=34, always=False, escape=None):\n+    output = bytearray()\n+    for row in rows:\n+        single = len(row) == 1\n+        output.extend(bytes([delim]).join(\n+            quote_field(bytes(field), delim, quote, always, escape, single)\n+            for field in row))\n+        output.extend(term)\n+    return bytes(output)\n+\n+\n+def write_output(data, path=None):\n+    if path in (None, \"-\"):\n+        sys.stdout.buffer.write(data)\n+        sys.stdout.buffer.flush()\n+    else:\n+        try:\n+            with open(path, \"wb\") as stream:\n+                stream.write(data)\n+        except OSError as error:\n+            raise CliError(str(error))\n+\n+\n+def output_delim(path, explicit=None):\n+    return explicit if explicit is not None else inferred_delimiter(path)\n+\n+\n+def common(args, extras=None, value_extras=None, defaults=None):\n+    aliases = {\n+        \"-n\": \"no_headers\", \"--no-headers\": \"no_headers\",\n+        \"-d\": \"delimiter\", \"--delimiter\": \"delimiter\",\n+        \"-o\": \"output\", \"--output\": \"output\",\n+    }\n+    aliases.update(extras or {})\n+    values = {\"delimiter\", \"output\"}\n+    values.update(value_extras or set())\n+    opts, pos = parse_options(args, aliases, values, defaults)\n+    opts[\"delimiter\"] = delimiter(opts[\"delimiter\"]) if opts.get(\"delimiter\") is not None else None\n+    return opts, pos\n+\n+\n+def split_selector(text):\n+    parts = []\n+    current = []\n+    quoted = False\n+    i = 0\n+    while i < len(text):\n+        char = text[i]\n+        if char == '\"':\n+            if quoted and i + 1 < len(text) and text[i + 1] == '\"':\n+                current.extend(['\"', '\"'])\n+                i += 2\n+                continue\n+            quoted = not quoted\n+        if char == ',' and not quoted:\n+            parts.append(\"\".join(current))\n+            current = []\n+        else:\n+            current.append(char)\n+        i += 1\n+    parts.append(\"\".join(current))\n+    return parts\n+\n+\n+def selector_endpoint(token, first, use_names, boundary=None):\n+    if boundary == \"start\":\n+        return 0\n+    if boundary == \"end\":\n+        return max(0, len(first) - 1)\n+    quoted = len(token) >= 2 and token[0] == '\"' and token[-1] == '\"'\n+    if quoted:\n+        token = token[1:-1].replace('\"\"', '\"')\n+    index_match = None if quoted else re.fullmatch(r\"[0-9]+\", token)\n+    if index_match:\n+        index = int(token)\n+        if index < 1 or index > len(first):\n+            raise CliError(\"Selector index {} is out of bounds. Index must be >= 1 and <= {}.\".format(index, len(first)))\n+        return index - 1\n+    occurrence = 0\n+    match = re.fullmatch(r\"(.*)\\[([0-9]+)\\]\", token)\n+    if match and not quoted:\n+        token, occurrence = match.group(1), int(match.group(2))\n+    if not use_names:\n+        raise CliError(\"Cannot use names ('{}') in selection with --no-headers set.\".format(token))\n+    raw = token.encode(\"utf-8\")\n+    found = [i for i, value in enumerate(first) if value == raw]\n+    if not found:\n+        raise CliError(\"Selector name '{}' does not exist as a named header in the given CSV data.\".format(token))\n+    if occurrence >= len(found):\n+        raise CliError(\"Selector index '{}' for name '{}' is out of bounds. Must be >= 0 and <= {}.\".format(occurrence, token, len(found) - 1))\n+    return found[occurrence]\n+\n+\n+def find_range_dash(part):\n+    quoted = False\n+    bracket = 0\n+    for i, char in enumerate(part):\n+        if char == '\"':\n+            quoted = not quoted\n+        elif not quoted:\n+            if char == '[':\n+                bracket += 1\n+            elif char == ']':\n+                bracket = max(0, bracket - 1)\n+            elif char == '-' and bracket == 0:\n+                return i\n+    return None\n+\n+\n+def select_indices(expression, first, use_names=True):\n+    invert = expression.startswith(\"!\")\n+    if invert:\n+        expression = expression[1:]\n+    if expression == \"\":\n+        return [] if invert else list(range(len(first)))\n+    selected = []\n+    for part in split_selector(expression):\n+        dash = find_range_dash(part)\n+        if dash is None:\n+            selected.append(selector_endpoint(part, first, use_names))\n+            continue\n+        left, right = part[:dash], part[dash + 1:]\n+        start = selector_endpoint(left, first, use_names, \"start\" if left == \"\" else None)\n+        end = selector_endpoint(right, first, use_names, \"end\" if right == \"\" else None)\n+        step = 1 if start <= end else -1\n+        selected.extend(range(start, end + step, step))\n+    if invert:\n+        omitted = set(selected)\n+        return [i for i in range(len(first)) if i not in omitted]\n+    return selected\n+\n+\n+def selected(row, indices):\n+    return [row[index] for index in indices]\n+\n+\n+def headers_command(args):\n+    opts, paths = common(args,\n+        {\"-j\": \"just\", \"--just-names\": \"just\", \"--intersect\": \"intersect\"})\n+    if opts.get(\"help\"):\n+        return USAGES[\"headers\"].encode()\n+    paths = paths or [\"-\"]\n+    if sum(path == \"-\" for path in paths) > 1:\n+        raise CliError(\"At most one <stdin> input is allowed.\")\n+    all_headers = []\n+    for path in paths:\n+        first, _, _ = read_csv(path, opts.get(\"delimiter\") or inferred_delimiter(path), True)\n+        for header in first:\n+            if not opts.get(\"intersect\") or header not in all_headers:\n+                all_headers.append(header)\n+    if len(paths) == 1 and not opts.get(\"just\"):\n+        width = len(str(len(all_headers)))\n+        return b\"\".join(str(i).encode() + b\" \" * (width + 2 - len(str(i))) + value + b\"\\n\"\n+                        for i, value in enumerate(all_headers, 1))\n+    return b\"\".join(value + b\"\\n\" for value in all_headers)\n+\n+\n+def count_command(args):\n+    opts, pos = common(args)\n+    if opts.get(\"help\"):\n+        return USAGES[\"count\"].encode()\n+    if len(pos) > 1:\n+        raise CliError(\"Invalid arguments for 'count'\")\n+    path = pos[0] if pos else None\n+    no_headers = bool(opts.get(\"no_headers\"))\n+    if os.environ.get(\"XSV_TOGGLE_HEADERS\", \"0\") == \"1\":\n+        no_headers = not no_headers\n+    _, records, _ = read_csv(path, opts.get(\"delimiter\") or inferred_delimiter(path), no_headers)\n+    return (str(len(records)) + \"\\n\").encode()\n+\n+\n+def select_command(args):\n+    opts, pos = common(args)\n+    if opts.get(\"help\"):\n+        return USAGES[\"select\"].encode()\n+    if not pos or len(pos) > 2:\n+        raise CliError(\"Invalid arguments for 'select'\")\n+    expression, path = pos[0], pos[1] if len(pos) == 2 else None\n+    no_headers = bool(opts.get(\"no_headers\"))\n+    if os.environ.get(\"XSV_TOGGLE_HEADERS\", \"0\") == \"1\":\n+        no_headers = not no_headers\n+    first, records, _ = read_csv(path, opts.get(\"delimiter\") or inferred_delimiter(path), no_headers)\n+    indices = select_indices(expression, first, not no_headers)\n+    rows = ([] if no_headers or not first else [selected(first, indices)])\n+    rows.extend(selected(row, indices) for row in records)\n+    out = opts.get(\"output\")\n+    write_output(encode_rows(rows, output_delim(out)), out)\n+    return None\n+\n+\n+def slice_command(args):\n+    extra = {\"-s\": \"start\", \"--start\": \"start\", \"-e\": \"end\", \"--end\": \"end\",\n+             \"-l\": \"len\", \"--len\": \"len\", \"-i\": \"index\", \"--index\": \"index\"}\n+    opts, pos = common(args, extra, {\"start\", \"end\", \"len\", \"index\"})\n+    if opts.get(\"help\"):\n+        return USAGES[\"slice\"].encode()\n+    if len(pos) > 1:\n+        raise CliError(\"Invalid arguments for 'slice'\")\n+    path = pos[0] if pos else None\n+    no_headers = bool(opts.get(\"no_headers\"))\n+    if os.environ.get(\"XSV_TOGGLE_HEADERS\", \"0\") == \"1\":\n+        no_headers = not no_headers\n+    first, records, _ = read_csv(path, opts.get(\"delimiter\") or inferred_delimiter(path), no_headers)\n+    out = opts.get(\"output\")\n+    out_delim = output_delim(out)\n+    header_bytes = b\"\" if no_headers or not first else encode_rows([first], out_delim)\n+    given = {name: uint(opts[name], \"--\" + name) for name in (\"start\", \"end\", \"len\", \"index\") if opts.get(name) is not None}\n+    if \"index\" in given and len(given) > 1:\n+        raise CliError(\"--index cannot be used with --start, --end or --len\", header_bytes)\n+    if \"end\" in given and \"len\" in given:\n+        raise CliError(\"--end and --len cannot be used at the same time.\", header_bytes)\n+    if \"index\" in given:\n+        start, end = given[\"index\"], given[\"index\"] + 1\n+    else:\n+        start = given.get(\"start\", 0)\n+        if \"end\" in given:\n+            end = given[\"end\"]\n+            if start > end:\n+                raise CliError(\"The end of the range ({}) must be greater than or\\nequal to the start of the range ({}).\".format(end, start), header_bytes)\n+        else:\n+            end = start + given[\"len\"] if \"len\" in given else len(records)\n+    data = header_bytes + encode_rows(records[start:end], out_delim)\n+    write_output(data, out)\n+    return None\n+\n+\n+def search_command(args):\n+    extra = {\"-i\": \"ignore\", \"--ignore-case\": \"ignore\", \"-s\": \"select\", \"--select\": \"select\",\n+             \"-v\": \"invert\", \"--invert-match\": \"invert\"}\n+    opts, pos = common(args, extra, {\"select\"}, {\"select\": \"\"})\n+    if opts.get(\"help\"):\n+        return USAGES[\"search\"].encode()\n+    if not pos or len(pos) > 2:\n+        raise CliError(\"Invalid arguments for 'search'\")\n+    pattern_text, path = pos[0], pos[1] if len(pos) == 2 else None\n+    try:\n+        pattern = re.compile(pattern_text.encode(\"utf-8\"), re.IGNORECASE if opts.get(\"ignore\") else 0)\n+    except re.error as error:\n+        raise CliError(str(error))\n+    no_headers = bool(opts.get(\"no_headers\"))\n+    if os.environ.get(\"XSV_TOGGLE_HEADERS\", \"0\") == \"1\":\n+        no_headers = not no_headers\n+    first, records, _ = read_csv(path, opts.get(\"delimiter\") or inferred_delimiter(path), no_headers)\n+    indices = select_indices(opts.get(\"select\", \"\"), first, not no_headers)\n+    result = [] if no_headers or not first else [first]\n+    for row in records:\n+        match = any(pattern.search(row[index]) is not None for index in indices)\n+        if bool(opts.get(\"invert\")) != match:\n+            result.append(row)\n+    out = opts.get(\"output\")\n+    write_output(encode_rows(result, output_delim(out)), out)\n+    return None\n+\n+\n+def lexical_compare(left, right, indices):\n+    for index in indices:\n+        if left[index] < right[index]:\n+            return -1\n+        if left[index] > right[index]:\n+            return 1\n+    return 0\n+\n+\n+def parse_number(raw):\n+    try:\n+        text = raw.decode(\"utf-8\")\n+    except UnicodeDecodeError:\n+        return None\n+    if re.fullmatch(r\"[+-]?[0-9]+\", text):\n+        value = int(text)\n+        if -(2 ** 63) <= value < 2 ** 63:\n+            return value\n+    if not re.fullmatch(r\"[+-]?(?:(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf|NaN)\", text):\n+        return None\n+    try:\n+        return float(text)\n+    except ValueError:\n+        return None\n+\n+\n+def numeric_compare(left, right, indices):\n+    for index in indices:\n+        a, b = parse_number(left[index]), parse_number(right[index])\n+        if a is None and b is None:\n+            return 0\n+        if a is None:\n+            return -1\n+        if b is None:\n+            return 1\n+        if isinstance(a, float) and math.isnan(a) or isinstance(b, float) and math.isnan(b):\n+            continue\n+        if a < b:\n+            return -1\n+        if a > b:\n+            return 1\n+    return 0\n+\n+\n+def sort_command(args):\n+    extra = {\"-s\": \"select\", \"--select\": \"select\", \"-N\": \"numeric\", \"--numeric\": \"numeric\",\n+             \"-R\": \"reverse\", \"--reverse\": \"reverse\"}\n+    opts, pos = common(args, extra, {\"select\"}, {\"select\": \"\"})\n+    if opts.get(\"help\"):\n+        return USAGES[\"sort\"].encode()\n+    if len(pos) > 1:\n+        raise CliError(\"Invalid arguments for 'sort'\")\n+    path = pos[0] if pos else None\n+    no_headers = bool(opts.get(\"no_headers\"))\n+    if os.environ.get(\"XSV_TOGGLE_HEADERS\", \"0\") == \"1\":\n+        no_headers = not no_headers\n+    first, records, _ = read_csv(path, opts.get(\"delimiter\") or inferred_delimiter(path), no_headers)\n+    indices = select_indices(opts.get(\"select\", \"\"), first, not no_headers)\n+    comparator = numeric_compare if opts.get(\"numeric\") else lexical_compare\n+    direction = -1 if opts.get(\"reverse\") else 1\n+    records.sort(key=cmp_to_key(lambda a, b: direction * comparator(a, b, indices)))\n+    rows = ([] if no_headers or not first else [first]) + records\n+    out = opts.get(\"output\")\n+    write_output(encode_rows(rows, output_delim(out)), out)\n+    return None\n+\n+\n+def condense(field, limit):\n+    if limit is None:\n+        return field\n+    try:\n+        text = field.decode(\"utf-8\")\n+    except UnicodeDecodeError:\n+        return field if len(field) <= limit else field[:limit] + b\"...\"\n+    return field if len(text) <= limit else \"\".join(list(text)[:limit]).encode(\"utf-8\") + b\"...\"\n+\n+\n+def table_command(args):\n+    extra = {\"-w\": \"width\", \"--width\": \"width\", \"-p\": \"pad\", \"--pad\": \"pad\",\n+             \"-c\": \"condense\", \"--condense\": \"condense\"}\n+    opts, pos = common(args, extra, {\"width\", \"pad\", \"condense\"}, {\"width\": \"2\", \"pad\": \"2\"})\n+    if opts.get(\"help\"):\n+        return USAGES[\"table\"].encode()\n+    if len(pos) > 1:\n+        